			instrument.duplicateCheckType = binary[offset + 18] & 3;
			instrument.duplicateCheckAction = binary[offset + 19] % 3;
			instrument.fadeout = readLittleEndian(binary, 2, offset + 20) << 5;
			instrument.pitchPanSeparation = binary[offset + 22] << 24 >> 24;
			instrument.pitchPanCenter = Math.min(119, binary[offset + 23]);
			instrument.globalVolume = Math.min(64, binary[offset + 24] >> 1);
			const panning = binary[offset + 25];
			if ((panning & 128) === 0) {
				instrument.panning = panning * 4;
				if (instrument.panning > 256) instrument.panning = 128;
			}
