		const loop = [binary[offset + 18], binary[offset + 19]];
		const sustain = [binary[offset + 20], binary[offset + 21]];
		instrument.volumeEnvelope = createEnvelope(points, flags & 1 | (Math.max(loop[0], loop[1]) < points.length ? flags & 2 : 0) | (Math.max(sustain[0], sustain[1]) < points.length ? flags & 4 : 0), loop[0], loop[1], sustain[0], sustain[1]);
