			const l = inputLeft[i];
			const r = inputRight[i];
			delayL.process(l * LINE_INPUT, phase);
			delayR.process(r * LINE_INPUT, phase);
			output.process(l, delayL.output[0] - delayR.output[0], r, delayR.output[1] - delayL.output[1]);
